BEGIN READ ONLY; SET LOCAL statement_timeout='10s';
SELECT 'functions' category,count(*) n,md5(string_agg(jsonb_build_object('signature',n.nspname||'.'||p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text)::text,E'\n' ORDER BY p.oid)) checksum FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.prokind IN ('f','p') AND NOT EXISTS (SELECT 1 FROM unnest(ARRAY[to_regprocedure('private.column_filter_predicate_v1(text,jsonb)'),to_regprocedure('private.column_filter_text_v1(text[])'),to_regprocedure('private.column_filter_phone_v1(text)'),to_regprocedure('private.column_filter_tag_values_v1(jsonb)'),to_regprocedure('private.column_filter_zalo_tags_v1(jsonb)'),to_regprocedure('private.column_filter_uri_decode_v1(text,boolean)'),to_regprocedure('private.column_filter_uri_encode_v1(text,boolean)'),to_regprocedure('private.column_filter_fb_url_v1(text,text)'),to_regprocedure('private.column_filter_source_match_v1(jsonb,jsonb)'),to_regprocedure('public.aka_agent_read_filtered_group_v1(bigint,bigint,text,text,jsonb)'),to_regprocedure('public.aka_agent_read_filtered_contacts_v1(bigint,bigint,text,text,text,jsonb)'),to_regprocedure('public.aka_agent_read_filtered_remarketing_v1(bigint,bigint,text,text,jsonb)')]::oid[]) target(oid) WHERE target.oid=p.oid)
UNION ALL SELECT 'relations',count(*),md5(string_agg(jsonb_build_object('oid',c.oid,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'owner',c.relowner,'acl',c.relacl)::text,E'\n' ORDER BY c.oid)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private')
UNION ALL SELECT 'policies',count(*),md5(string_agg(to_jsonb(p)::text,E'\n' ORDER BY p.oid)) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private')
UNION ALL SELECT 'columns',count(*),md5(string_agg(jsonb_build_object('rel',a.attrelid,'num',a.attnum,'name',a.attname,'type',a.atttypid,'mod',a.atttypmod,'null',a.attnotnull,'acl',a.attacl,'def',pg_get_expr(d.adbin,d.adrelid))::text,E'\n' ORDER BY a.attrelid,a.attnum)) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname IN ('public','private') AND a.attnum>0 AND NOT a.attisdropped
UNION ALL SELECT 'role_database_settings',count(*),md5(string_agg(to_jsonb(s)::text,E'\n' ORDER BY setdatabase,setrole)) FROM pg_db_role_setting s;
COMMIT;
